$notice = $_SESSION['flash'] ?? null; unset($_SESSION['flash']);
$initials = strtoupper(implode('',array_map(fn($part)=>substr($part,0,1),array_slice(preg_split('/\s+/',trim($account['name'])),0,2))));
$stages = ['Site survey','Design approval','Permits & approvals','Installation','System activation'];
function status_badge(string $status): string { $class = in_array($status,['Paid','Resolved','Confirmed','Completed'],true)?'good':(in_array($status,['Due','Requested','Open','In progress'],true)?'warm':'neutral'); return '<span class="status-badge '.$class.'">'.e($status).'</span>'; }
function empty_state(string $text): void { echo '<div class="empty-state">'.icon('file').'<p>'.e($text).'</p></div>'; }
