<div class="row g-3"><div class="col-lg-7"><section class="panel"><div class="panel-heading"><h2>Service desk</h2><span class="muted small"><?=count($allTickets)?> tickets</span></div><?php foreach ($allTickets as $t): ?><form class="ticket-card" action="actions.php" method="post"><?=csrf_field()?><input type="hidden" name="action" value="admin_ticket"><input type="hidden" name="id" value="<?=$t['id']?>"><span class="eyebrow"><?=e($t['name'])?> · #<?=$t['id']?></span><h3><?=e($t['subject'])?></h3><p class="ticket-message"><?=nl2br(e($t['message']))?></p><label class="form-label" for="reply-<?=$t['id']?>">Reply to customer</label><textarea class="form-control mb-3" id="reply-<?=$t['id']?>" name="reply" maxlength="4000" rows="2"><?=e($t['reply'])?></textarea><div class="d-flex gap-2"><label class="visually-hidden" for="status-<?=$t['id']?>">Ticket status</label><select class="form-select" name="status" id="status-<?=$t['id']?>"><?php foreach (['Open','In progress','Resolved'] as $s): ?><option <?=$t['status']===$s?'selected':''?>><?=$s?></option><?php endforeach; ?></select><button class="btn btn-accent text-nowrap">Save reply</button></div></form><?php endforeach; ?></section></div><div class="col-lg-5"><section class="panel"><div class="panel-heading"><h2>Visit requests</h2><?=icon('calendar')?></div><?php foreach ($allVisits as $a): ?><form class="ticket-card" action="actions.php" method="post"><?=csrf_field()?><input type="hidden" name="action" value="admin_appointment"><input type="hidden" name="id" value="<?=$a['id']?>"><span class="eyebrow"><?=e($a['name'])?></span><h3><?=e($a['type'])?></h3><p class="muted"><?=e($a['date'])?> · <?=e($a['time'])?> PKT</p><p class="small"><?=e($a['notes'])?></p><div class="d-flex gap-2"><label class="visually-hidden" for="visit-status-<?=$a['id']?>">Visit status</label><select class="form-select" name="status" id="visit-status-<?=$a['id']?>"><?php foreach (['Requested','Confirmed','Completed','Cancelled'] as $s): ?><option <?=$a['status']===$s?'selected':''?>><?=$s?></option><?php endforeach; ?></select><button class="btn btn-accent">Save</button></div></form><?php endforeach; ?></section></div></div><section class="panel mt-3"><div class="panel-heading"><h2>Recent account activity</h2><?=icon('shield')?></div><?php foreach (query('SELECT a.*,u.name FROM audit a JOIN users u ON u.id=a.user_id ORDER BY a.id DESC LIMIT 10') as $a): ?><div class="audit-row"><strong><?=e($a['name'])?></strong><span><?=e($a['action'])?></span><small class="muted"><?=e($a['created_at'])?> PKT</small></div><?php endforeach; ?></section>
